const normalize = v => String(v || '').replace(/[\u200c\u200f\u200e\s]+/g,' ').replace(/[«»\"'?!.,:؛،()[\]{}\-–—_\/]/g,'').trim().toLowerCase();
const now = new Date();
const analysisTime = new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',dateStyle:'full',timeStyle:'short'}).format(now);
const dated = items.map(item => { const j=item.json||{}; const ts=Date.parse(j.isoDate||j.pubDate||j.pubdate||'')||0; const title=String(j.title||'').replace(/\s+/g,' ').trim(); const description=String(j.contentSnippet||j.content||j.description||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(); const source=String(j.creator||j.author||j.source||'').trim(); const link=String(j.link||'').trim(); return {ts,title,description,source,link}; }).sort((a,b)=>b.ts-a.ts);
const seen=new Set(); const news=[];
for(const e of dated){ if(!e.title) continue; const key=normalize(e.title); if(!key || seen.has(key)) continue; seen.add(key); news.push({no:news.length+1,title:e.title,description:e.description,source:e.source,link:e.link,publishedAt:e.ts?new Date(e.ts).toISOString():''}); }
const newsText=news.map(n=>{ const p=[`${n.no}. ${n.title}`]; if(n.description)p.push(`خلاصه: ${n.description.slice(0,500)}`); if(n.source)p.push(`منبع: ${n.source}`); if(n.publishedAt)p.push(`تاریخ انتشار: ${n.publishedAt}`); if(n.link)p.push(`لینک: ${n.link}`); return p.join('\n'); }).join('\n\n');
return [{json:{analysisTime,count:news.length,news,newsText:newsText||'هیچ خبری از RSSها دریافت نشد.'}}];

// Telegram sendMessage حداکثر 4096 کاراکتر دارد. برای حاشیه امن، هر پیام را حداکثر 3800 کاراکتر می‌کنیم.
const LIMIT = 3800;
const input = String($json.text || '').trim();
if (!input) return [];

const splitLong = (text) => {
  const chunks = [];
  let rest = text.trim();
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n\n', LIMIT);
    if (cut < Math.floor(LIMIT * 0.55)) cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < Math.floor(LIMIT * 0.55)) cut = rest.lastIndexOf(' ', LIMIT);
    if (cut < Math.floor(LIMIT * 0.55)) cut = LIMIT;
    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) chunks.push(rest);
  return chunks.filter(Boolean);
};

const chunks = splitLong(input);
return chunks.map((text,index) => ({json:{text,part:index+1,totalParts:chunks.length}}));
